const ROWS: RouteRow[] = FIXTURE.rows.map((row) => ({
  articleId: row.article_id, vendor: row.vendor, tier: row.tier, relevance: row.relevance, direction: row.direction,
  title: row.title, seenEpoch: row.seen_epoch, score: row.score,
}));

function close(actual: number | null, expected: number | null, tolerance = 1e-9): void {
  if (expected === null) {
    expect(actual).toBeNull();
    return;
  }
  expect(actual).not.toBeNull();
  expect(Math.abs((actual as number) - expected)).toBeLessThanOrEqual(tolerance);
}

describe("collapseRows and mergeSpans match lake.sentiment", () => {
  const stories = collapseRows(ROWS);

  it("keeps one story per distinct headline, with the Python's known time, weight, score and macro weight", () => {
    expect(stories).toHaveLength(FIXTURE.stories.known_at.length);
    stories.forEach((story, i) => {
      close(story.knownAt, FIXTURE.stories.known_at[i] as number, 1e-6);
      close(story.weight, FIXTURE.stories.weight[i] as number, 1e-12);
      close(story.score, FIXTURE.stories.score[i] as number, 1e-12);
      close(story.macroWeight, FIXTURE.stories.macro_weight[i] as number, 1e-12);
    });
  });

  it("counts a syndicated copy once, a later route never raises an earlier weight, and GDELT is known 15 minutes late", () => {
    const titles = new Set(stories.map((story) => story.title));
    expect(titles.has("FED holds rates -- steady")).toBe(false); // a3: the same story within two hours
    expect(stories.filter((story) => story.title === "Fed holds rates steady")).toHaveLength(2); // a1, then a4 after the window
    expect(stories[0]?.weight).toBe(1.0); // a1's later route (relevance 1.0 at +4000 s) is not knowable at +600 s; the macro route is
    const gdelt = ROWS.find((row) => row.articleId === "a2") as RouteRow;
    expect(knownAtOf(gdelt)).toBe(gdelt.seenEpoch + 900);
    const euro = stories.find((story) => story.title.startsWith("Euro"));
    expect(euro?.weight).toBeCloseTo(0.3 - 0.6, 12); // max(+1 relevances) - max(-1 relevances)
  });

  it("merges coverage spans closer than 30 minutes", () => {
    expect(mergeSpans(FIXTURE.coverage_spans)).toEqual(FIXTURE.merged);
  });

  it("normalises titles the way the Python does", () => {
    expect(normaliseTitle("FED holds rates -- steady")).toBe("fed holds rates steady");
    expect(normaliseTitle(null)).toBe("");
  });
});

describe("computeFeatures matches lake.sentiment.compute_from_stream to 1e-9", () => {
  const stream = { stories: collapseRows(ROWS), coverage: mergeSpans(FIXTURE.coverage_spans) };
  for (const grid of FIXTURE.grids) {
    it(`${grid.minutes}-minute grid, all nine columns on ${grid.count} bars`, () => {
      const times = Float64Array.from({ length: grid.count }, (_, i) => grid.start + i * grid.minutes * 60);
      const columns = computeFeatures(times, stream, grid.minutes);
      FEATURE_NAMES.forEach((name: FeatureName, c) => {
        const expected = grid.features[c] as number[];
        const actual = columns[name];
        expect(actual).toHaveLength(grid.count);
        for (let b = 0; b < grid.count; b += 1) close(actual[b] as number, expected[b] as number, 1e-9);
      });
    });
  }

  it("scales the half-lives and window with the bar grid", () => {
    expect(featureScales(1)).toEqual({ shortSeconds: 1200, longSeconds: 86_400, windowSeconds: 3600 });
    expect(featureScales(60)).toEqual({ shortSeconds: 14_400, longSeconds: 115_200, windowSeconds: 28_800 });
  });

  it("reads a bar as unknown-news (all zeros, coverage 0) before any headline or span", () => {
    const empty = computeFeatures(Float64Array.of(1_000, 2_000), { stories: [], coverage: [] }, 5);
    for (const name of FEATURE_NAMES) {
      if (name === "finbert_minutes_since_article_log") expect(empty[name][0]).toBeCloseTo(Math.log1p(7 * 24 * 60), 12);
      else expect(Array.from(empty[name])).toEqual([0, 0]);
    }
  });
});

describe("decayStep: S(t) term by term", () => {
  const stories = collapseRows(ROWS);
  const step = decayStep(stories, FIXTURE.step.t, FIXTURE.step.half_life_minutes);

  it("equals the notebook's stepper sum and the value the model sees", () => {
    expect(step.knownCount).toBe(FIXTURE.step.known_count);
    close(step.sum, FIXTURE.step.sum, 1e-12);
    close(step.modelValue, FIXTURE.step.model_value, 1e-12);
    close(step.terms.reduce((total, term) => total + term.term, 0), step.sum, 1e-12);
  });

  it("lists the terms newest first with their ages and decayed values", () => {
    step.terms.forEach((term, i) => {
      const [age, value] = FIXTURE.step.terms_newest_first[i] as [number, number];
      close(term.ageMinutes, age, 1e-9);
      close(term.term, value, 1e-12);
    });
  });

  it("uses only headlines known strictly before the bar opens", () => {
    const at = stories[0]?.knownAt as number;
    expect(decayStep(stories, at, 20).knownCount).toBe(0);
    expect(decayStep(stories, at + 1, 20).knownCount).toBe(1);
  });
});

describe("eightNumbers follows the notebook's moments", () => {
  for (const [name, input] of Object.entries(FIXTURE.eight_inputs)) {
    it(`${name}`, () => {
      const expected = FIXTURE.eight[name] as Record<string, number | null>;
      const actual = eightNumbers(input.map((value) => (value === null ? Number.NaN : value)));
      expect(actual.count).toBe(expected.count);
      close(actual.mean, expected.mean ?? null);
      close(actual.median, expected.median ?? null);
      close(actual.standardDeviation, expected.standard_deviation ?? null);
      close(actual.skewness, expected.skewness ?? null);
      close(actual.excessKurtosis, expected.excess_kurtosis ?? null);
      close(actual.percentile25, expected.percentile_25 ?? null);
      close(actual.percentile75, expected.percentile_75 ?? null);
      close(actual.minimum, expected.min ?? null);
      close(actual.maximum, expected.max ?? null);
    });
  }

  it("has no moments for an empty column", () => {
    expect(eightNumbers([]).count).toBe(0);
    expect(eightNumbers([Number.NaN]).mean).toBeNull();
  });
});

describe("small helpers", () => {
  it("searchLeft and searchRight are numpy.searchsorted", () => {
    const a = [1, 2, 2, 4];
    expect([searchLeft(a, 2), searchRight(a, 2), searchLeft(a, 0), searchRight(a, 9)]).toEqual([1, 3, 0, 4]);
  });

  it("barGrid is numpy.arange and keeps the newest bars past the cap", () => {
    const grid = barGrid(0, 3600, 5);
    expect(grid.times).toHaveLength(12);
    expect(grid.times[11]).toBe(3300);
    const capped = barGrid(0, 3600, 5, 4);
    expect(capped.truncated).toBe(true);
    expect(Array.from(capped.times)).toEqual([2400, 2700, 3000, 3300]);
  });

  it("signedLog keeps the sign", () => {
    expect(signedLog(-3)).toBeCloseTo(-Math.log(4), 12);
    expect(signedLog(0)).toBe(0);
  });

  it("a GDELT span reaches only the roots its query maps to; a feed reaches every root", () => {
    const reach = new Map([["fomc", new Set(["MNQ", "ES"])]]);
    expect(sourceReaches("gdelt", "fomc", "MNQ", reach)).toBe(true);
    expect(sourceReaches("gdelt", "fomc", "EURUSD", reach)).toBe(false);
    expect(sourceReaches("gdelt", "unknown_tag", "MNQ", reach)).toBe(false);
    expect(sourceReaches("rss", "yahoo_finance", "EURUSD", reach)).toBe(true);
  });
});

// ── the handler, against a fake lake ──────────────────────────────────────

interface Recorded {
  sql: string[];
}

function fakeLake(recorded: Recorded, options: { rootsView?: boolean; queryRootsView?: boolean; empty?: boolean } = {}): StudyLake {
  const rootsView = options.rootsView ?? true;
  const queryRootsView = options.queryRootsView ?? true;
  return {
    async query<T>(sql: string): Promise<T[]> {
      recorded.sql.push(sql);
      if (sql.startsWith("DESCRIBE")) {
        return ["article_id", "seen_ts", "vendor", "direction", "root", "tier", "relevance", "title"].map((column_name) => ({ column_name })) as T[];
      }
      if (sql.startsWith("WITH routes")) {
        if (options.empty) return [];
        // the real SQL orders by seen time
        return FIXTURE.rows.map((row) => ({ ...row })).sort((a, b) => a.seen_epoch - b.seen_epoch) as unknown as T[];
      }
      if (sql.includes("FROM read_parquet('s3://curated/news_coverage")) {
        return [
          { vendor: "gdelt", source: "fomc", start_epoch: FIXTURE.coverage_spans[0]?.[0], end_epoch: FIXTURE.coverage_spans[0]?.[1] },
          { vendor: "gdelt", source: "other_query", start_epoch: 1, end_epoch: 2_000_000_000 },
          { vendor: "rss", source: "yahoo_finance", start_epoch: FIXTURE.coverage_spans[1]?.[0], end_epoch: FIXTURE.coverage_spans[1]?.[1] },
          { vendor: "rss", source: "investing", start_epoch: FIXTURE.coverage_spans[2]?.[0], end_epoch: FIXTURE.coverage_spans[2]?.[1] },
          { vendor: "rss", source: "investing", start_epoch: FIXTURE.coverage_spans[3]?.[0], end_epoch: FIXTURE.coverage_spans[3]?.[1] },
        ] as unknown as T[];
      }
      if (sql.includes("SELECT DISTINCT query_tag")) return [{ query_tag: "fomc" }] as T[];
      if (sql.includes("SELECT instrument_root")) return [{ instrument_root: "MNQ" }, { instrument_root: "EURUSD" }] as T[];
      if (sql.includes("SELECT DISTINCT root")) return [{ root: "ES" }, { root: "MNQ" }] as T[];
      return [];
    },
    async hasView(name) {
      if (name.includes("query_roots")) return queryRootsView;
      return rootsView;
    },
    async columns() {
      return [];
    },
  };
}

function contextOf(lake: StudyLake): StudyContext {
  return { lake, notes: [] };
}

const handler = createHandler({ spoolDirs: () => [] });
const QUERY = handler.query.parse({ root: "mnq", start: "2026-09-21", end: "2026-09-21" });

describe("the handler", () => {
  it("parses the root to upper case and refuses anything that is not a plain symbol or a calendar date", () => {
    expect(QUERY.root).toBe("MNQ");
    expect(handler.query.safeParse({ root: "MNQ'; DROP TABLE x; --" }).success).toBe(false);
    expect(handler.query.safeParse({ start: "2026-13-45" }).success).toBe(false);
    expect(handler.query.safeParse({ start: "yesterday" }).success).toBe(false);
    expect(handler.query.parse({}).root).toBe("MNQ");
  });

  it("returns the collapsed stories, the window's headlines and routes, and the coverage that reaches the root", async () => {
    const recorded: Recorded = { sql: [] };
    const context = contextOf(fakeLake(recorded));
    const body = await handler.run(QUERY, context);
    expect(body.root).toBe("MNQ");
    expect(body.roots).toEqual(["MNQ", "EURUSD"]);
    expect(body.windowStartMs).toBe(Date.parse("2026-09-21T00:00:00Z"));
    expect(body.windowEndMs).toBe(Date.parse("2026-09-22T00:00:00Z"));
    expect(body.routeCount).toBe(FIXTURE.rows.length);
    expect(body.distinctHeadlineCount).toBe(new Set(FIXTURE.rows.map((row) => row.article_id)).size);
    expect(body.stories).toHaveLength(FIXTURE.stories.known_at.length);
    expect(body.routes[0]?.seenMs).toBeGreaterThanOrEqual(body.routes[body.routes.length - 1]?.seenMs ?? 0); // newest first
    expect(body.headlines.every((route, i, all) => i === 0 || (all[i - 1] as { seenMs: number }).seenMs <= route.seenMs)).toBe(true);
    // the fomc GDELT span reaches MNQ, the other query does not, the feeds always do, and spans under 30 minutes apart merge
    expect(body.coverage).toEqual(FIXTURE.merged);
    expect(context.notes).toEqual([]);
  });

  it("puts only validated, quoted values into SQL, with the 45-day lookback and the model filter", async () => {
    const recorded: Recorded = { sql: [] };
    await handler.run(QUERY, contextOf(fakeLake(recorded)));
    const routes = recorded.sql.find((sql) => sql.startsWith("WITH routes")) as string;
    expect(routes).toContain("root = 'MNQ'");
    expect(routes).toContain("model = 'ProsusAI/finbert'");
    const start = Date.parse("2026-09-21T00:00:00Z") / 1000;
    expect(routes).toContain(`seen_ts >= to_timestamp(${start - 45 * 86_400})`);
    expect(routes).toContain(`seen_ts < to_timestamp(${start + 86_400 + 60})`);
    expect(routes).toContain("arg_min(score, source_rank)");
  });

  it("degrades to notes, never an error, when the reference views are not landed or no news exists", async () => {
    const recorded: Recorded = { sql: [] };
    const context = contextOf(fakeLake(recorded, { rootsView: false, queryRootsView: false, empty: true }));
    const body = await handler.run(QUERY, context);
    expect(body.roots).toEqual(["ES", "MNQ"]);
    expect(body.stories).toEqual([]);
    expect(body.routeCount).toBe(0);
    expect(context.notes.some((note) => note.includes("derived_study_finbert_sentiment_roots"))).toBe(true);
    expect(context.notes.some((note) => note.includes("No scored headlines routed to MNQ"))).toBe(true);
  });

  it("clamps a window that ends before it starts and one longer than 366 days", async () => {
    const context = contextOf(fakeLake({ sql: [] }));
    const reversed = await handler.run(handler.query.parse({ start: "2026-09-25", end: "2026-09-21" }), context);
    expect(reversed.windowStartMs).toBe(Date.parse("2026-09-21T00:00:00Z"));
    const long = contextOf(fakeLake({ sql: [] }));
    const capped = await handler.run(handler.query.parse({ start: "2020-01-01", end: "2026-09-21" }), long);
    expect((capped.windowEndMs - capped.windowStartMs) / 86_400_000).toBe(366);
    expect(long.notes.some((note) => note.includes("capped at 366 days"))).toBe(true);
  });

  it("lists the two landed reference views as its datasets", () => {
    expect(handler.slug).toBe("finbert-sentiment");
    expect(handler.datasets).toEqual(["derived_study_finbert_sentiment_roots", "derived_study_finbert_sentiment_query_roots"]);
  });
});

// ── the page's data preparation ───────────────────────────────────────────

function route(vendor: string, score: number, seenMs: number, tier = "index", direction = 1): NewsRoute {
  return { articleId: `${vendor}-${seenMs}`, vendor, tier, relevance: 0.5, direction, title: "t", seenMs, score };
}

describe("page preparation", () => {
  const hour = 3_600_000;
  const base = Date.parse("2026-09-21T10:30:00Z");
  const headlines = [route("gdelt", -1, base), route("rss", 0, base + hour), route("rss", 0.99, base + 3 * hour), route("alphavantage", 1, base + 3 * hour, "macro", -1)];

  it("orders vendors as the notebook's legend did and keeps unknown ones after", () => {
    expect(vendorsOf([...headlines, route("zeta", 0, base)])).toEqual(["gdelt", "rss", "alphavantage", "zeta"]);
  });

  it("bins scores over -1..1 per vendor and puts both extremes in the end bins", () => {
    const bins = scoreHistogram(headlines, 10, ["gdelt", "rss", "alphavantage"]);
    expect(bins).toHaveLength(10);
    expect(bins[0]?.gdelt).toBe(1);
    expect(bins[5]?.rss).toBe(1); // score 0 falls in [0, 0.2)
    expect(bins[9]?.rss).toBe(1);
    expect(bins[9]?.alphavantage).toBe(1);
    expect(bins.reduce((total, bin) => total + bin.total, 0)).toBe(headlines.length);
  });

  it("counts headlines per UTC hour, zero-filled, and widens the bucket past the bar cap", () => {
    const { buckets, bucketHours } = hourlyCounts(headlines, ["gdelt", "rss", "alphavantage"]);
    expect(bucketHours).toBe(1);
    expect(buckets).toHaveLength(4); // 10:00, 11:00, 12:00, 13:00
    expect(buckets.map((bucket) => bucket.total)).toEqual([1, 1, 0, 2]);
    expect(buckets[0]?.startMs).toBe(Date.parse("2026-09-21T10:00:00Z"));
    const wide = hourlyCounts([route("rss", 0, base), route("rss", 0, base + 1000 * hour)], ["rss"], 100);
    expect(wide.bucketHours).toBe(12);
    expect(wide.buckets.reduce((total, bucket) => total + bucket.total, 0)).toBe(2);
    expect(hourlyCounts([], ["rss"]).buckets).toEqual([]);
  });

  it("counts by category, most frequent first", () => {
    expect(countBy(headlines, (headline) => headline.tier)).toEqual([{ key: "index", count: 3 }, { key: "macro", count: 1 }]);
  });

  it("thins a long series to its cap keeping the first and last point, and leaves a short one alone", () => {
    const times = Float64Array.from({ length: 1000 }, (_, i) => i);
    const thin = thinSeries(times, times, 100);
    expect(thin).toHaveLength(100);
    expect(thin[0]?.time).toBe(0);
    expect(thin[99]?.time).toBe(999);
    expect(thinSeries(times.subarray(0, 5), times.subarray(0, 5), 100)).toHaveLength(5);
    expect(strideSample([1, 2, 3, 4, 5, 6], 3)).toEqual([1, 3, 5]);
  });

  it("formats a UTC calendar date some days back", () => {
    expect(utcDate(Date.parse("2026-09-30T23:59:00Z"), 3)).toBe("2026-09-27");
  });
});
